#include "spacecom_store.h"
#include <sqlite3.h>

static void Err(sqlite3*db,std::string&e){e=sqlite3_errmsg(db);}
Store::~Store(){if(db_)sqlite3_close(db_);}
bool Store::Exec(const std::string&s,std::string&e){char*x=nullptr;if(sqlite3_exec(db_,s.c_str(),nullptr,nullptr,&x)!=SQLITE_OK){e=x?x:sqlite3_errmsg(db_);sqlite3_free(x);return false;}return true;}
bool Store::Open(const std::string&p,std::string&e){if(sqlite3_open_v2(p.c_str(),&db_,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,nullptr)!=SQLITE_OK){Err(db_,e);return false;}return Exec("PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; CREATE TABLE IF NOT EXISTS outbound(id TEXT PRIMARY KEY,name TEXT NOT NULL,path TEXT NOT NULL,sha256 TEXT NOT NULL,size INTEGER NOT NULL,mode INTEGER NOT NULL,mtime INTEGER NOT NULL,state TEXT NOT NULL,retries INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT ''); CREATE INDEX IF NOT EXISTS outbound_ready ON outbound(state,next_attempt); CREATE TABLE IF NOT EXISTS received(id TEXT PRIMARY KEY,name TEXT NOT NULL,sha256 TEXT NOT NULL,size INTEGER NOT NULL,committed_at INTEGER NOT NULL DEFAULT(unixepoch())); CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,ok INTEGER NOT NULL,reason TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued');",e);}
bool Store::Recover(std::string&e){return Exec("UPDATE outbound SET state='queued' WHERE state IN ('sending','transport_acked'); UPDATE receipts SET state='queued' WHERE state='sending';",e);}
static bool BindRow(sqlite3_stmt*s,const TransferRow&r){return sqlite3_bind_text(s,1,r.id.c_str(),-1,SQLITE_TRANSIENT)==SQLITE_OK&&sqlite3_bind_text(s,2,r.name.c_str(),-1,SQLITE_TRANSIENT)==SQLITE_OK&&sqlite3_bind_text(s,3,r.path.c_str(),-1,SQLITE_TRANSIENT)==SQLITE_OK&&sqlite3_bind_text(s,4,r.sha256.c_str(),-1,SQLITE_TRANSIENT)==SQLITE_OK&&sqlite3_bind_int64(s,5,r.size)==SQLITE_OK&&sqlite3_bind_int(s,6,r.mode)==SQLITE_OK&&sqlite3_bind_int64(s,7,r.mtime)==SQLITE_OK;}
bool Store::Add(const TransferRow&r,std::string&e){sqlite3_stmt*s=nullptr;const char*q="INSERT INTO outbound(id,name,path,sha256,size,mode,mtime,state) VALUES(?,?,?,?,?,?,?,'queued')";if(sqlite3_prepare_v2(db_,q,-1,&s,nullptr)!=SQLITE_OK||!BindRow(s,r)){Err(db_,e);sqlite3_finalize(s);return false;}int x=sqlite3_step(s);sqlite3_finalize(s);if(x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
static void Read(sqlite3_stmt*s,TransferRow&r){r.id=(const char*)sqlite3_column_text(s,0);r.name=(const char*)sqlite3_column_text(s,1);r.path=(const char*)sqlite3_column_text(s,2);r.sha256=(const char*)sqlite3_column_text(s,3);r.size=sqlite3_column_int64(s,4);r.mode=sqlite3_column_int(s,5);r.mtime=sqlite3_column_int64(s,6);r.state=(const char*)sqlite3_column_text(s,7);r.retries=sqlite3_column_int(s,8);r.next_attempt=sqlite3_column_int64(s,9);r.last_error=(const char*)sqlite3_column_text(s,10);}
bool Store::Next(uint64_t now,TransferRow&r,bool&found,std::string&e){sqlite3_stmt*s=nullptr;const char*q="SELECT id,name,path,sha256,size,mode,mtime,state,retries,next_attempt,last_error FROM outbound WHERE state IN ('queued','transport_acked') AND next_attempt<=? ORDER BY rowid LIMIT 1";if(sqlite3_prepare_v2(db_,q,-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}sqlite3_bind_int64(s,1,now);int x=sqlite3_step(s);found=x==SQLITE_ROW;if(found)Read(s,r);else if(x!=SQLITE_DONE)Err(db_,e);sqlite3_finalize(s);return x==SQLITE_ROW||x==SQLITE_DONE;}
bool Store::SetState(const std::string&id,const std::string&st,uint64_t next,const std::string&d,std::string&e){sqlite3_stmt*s=nullptr;const char*q="UPDATE outbound SET state=?,next_attempt=?,last_error=?,retries=retries+CASE WHEN ?='queued' AND length(?)>0 THEN 1 ELSE 0 END WHERE id=?";if(sqlite3_prepare_v2(db_,q,-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}sqlite3_bind_text(s,1,st.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,2,next);sqlite3_bind_text(s,3,d.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,st.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,d.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,6,id.c_str(),-1,SQLITE_TRANSIENT);int x=sqlite3_step(s);sqlite3_finalize(s);if(x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
bool Store::Complete(const std::string&id,std::string&e){return SetState(id,"complete",0,"",e);}
bool Store::IsReceived(const std::string&id,bool&yes,std::string&e){sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db_,"SELECT 1 FROM received WHERE id=?",-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}sqlite3_bind_text(s,1,id.c_str(),-1,SQLITE_TRANSIENT);int x=sqlite3_step(s);yes=x==SQLITE_ROW;sqlite3_finalize(s);if(x!=SQLITE_ROW&&x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
bool Store::RecordReceived(const TransferRow&r,std::string&e){sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db_,"INSERT OR IGNORE INTO received(id,name,sha256,size) VALUES(?,?,?,?)",-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}sqlite3_bind_text(s,1,r.id.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,r.name.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,r.sha256.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,4,r.size);int x=sqlite3_step(s);sqlite3_finalize(s);if(x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
bool Store::QueueReceipt(const std::string&id,bool ok,const std::string&r,std::string&e){sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db_,"INSERT INTO receipts(id,ok,reason,state) VALUES(?,?,?,'queued') ON CONFLICT(id) DO UPDATE SET ok=excluded.ok,reason=excluded.reason,state='queued'",-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}sqlite3_bind_text(s,1,id.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,2,ok);sqlite3_bind_text(s,3,r.c_str(),-1,SQLITE_TRANSIENT);int x=sqlite3_step(s);sqlite3_finalize(s);if(x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
bool Store::NextReceipt(TransferRow&r,bool&found,std::string&e){sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db_,"SELECT id,ok,reason FROM receipts WHERE state='queued' ORDER BY rowid LIMIT 1",-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}int x=sqlite3_step(s);found=x==SQLITE_ROW;if(found){r=TransferRow();r.id=(const char*)sqlite3_column_text(s,0);r.state=sqlite3_column_int(s,1)?"OK":"ERROR";r.last_error=(const char*)sqlite3_column_text(s,2);}sqlite3_finalize(s);if(x!=SQLITE_ROW&&x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
bool Store::ReceiptSent(const std::string&id,std::string&e){sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db_,"UPDATE receipts SET state='sent' WHERE id=?",-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}sqlite3_bind_text(s,1,id.c_str(),-1,SQLITE_TRANSIENT);int x=sqlite3_step(s);sqlite3_finalize(s);if(x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
bool Store::List(std::vector<TransferRow>&v,std::string&e){sqlite3_stmt*s=nullptr;if(sqlite3_prepare_v2(db_,"SELECT id,name,path,sha256,size,mode,mtime,state,retries,next_attempt,last_error FROM outbound ORDER BY rowid",-1,&s,nullptr)!=SQLITE_OK){Err(db_,e);return false;}int x;while((x=sqlite3_step(s))==SQLITE_ROW){TransferRow r;Read(s,r);v.push_back(r);}sqlite3_finalize(s);if(x!=SQLITE_DONE){Err(db_,e);return false;}return true;}
